    public function getSenderEmail(): string
    {
        return $this->_senderEmail->value();
    }
    public function senderEmail(): SmtpOutboundConfigSenderEmailVO
    {
        return $this->_senderEmail;
    }
    public function isSenderEmailChanged(?self $original = null): bool
    {
        return !$this->_senderEmail->equals($original?->_senderEmail);
    }
    public function withSenderEmail(SmtpOutboundConfigSenderEmailVO|string $senderEmail): self
    {
        $copy = clone $this;
